  helpDebiti: 'Las deudas, divididas en préstamos a plazos y líneas de crédito.\n• «Nuevo pasivo» crea la cuenta; «Configurar deuda» describe sus condiciones: tipo, capital, tipo de interés, frecuencia y estructura de la cuota, disposiciones en tramos, carencia, vencimiento. Una línea de crédito tiene en cambio un límite y muestra uso y exposición.\n• Para cada préstamo ves el plan previsto, la deuda realmente generada y los pagos hechos, plan frente a realidad y el cuadro de amortización.\n• «Registrar cuota» abre un movimiento ya dividido en capital e intereses. Los movimientos de la cuenta «Sin clasificar» deben asignarse a capital o intereses.\n• Eliminar una deuda crea antes una copia de seguridad y pide confirmar el nombre de la cuenta.',
